1  import type {MarkdownStyle} from '@expensify/react-native-live-markdown';
     2  import lodashDebounce from 'lodash/debounce';
     3  import type {BaseSyntheticEvent, ForwardedRef} from 'react';
     4  import React, {useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';
     5  // eslint-disable-next-line no-restricted-imports
     6  import type {NativeSyntheticEvent, TextInput, TextInputKeyPressEventData, TextInputSelectionChangeEventData} from 'react-native';
     7  import {DeviceEventEmitter, StyleSheet} from 'react-native';
     8  import type {ComposerProps} from '@components/Composer/types';
     9  import type {AnimatedMarkdownTextInputRef} from '@components/RNMarkdownTextInput';
    10  import RNMarkdownTextInput from '@components/RNMarkdownTextInput';
    11  import useHtmlPaste from '@hooks/useHtmlPaste';
    12  import useIsScrollBarVisible from '@hooks/useIsScrollBarVisible';
    13  import useMarkdownStyle from '@hooks/useMarkdownStyle';
    14  import useStyleUtils from '@hooks/useStyleUtils';
    15  import useTheme from '@hooks/useTheme';
    16  import useThemeStyles from '@hooks/useThemeStyles';
    17  import addEncryptedAuthTokenToURL from '@libs/addEncryptedAuthTokenToURL';
    18  import * as Browser from '@libs/Browser';
    19  import updateIsFullComposerAvailable from '@libs/ComposerUtils/updateIsFullComposerAvailable';
    20  import * as EmojiUtils from '@libs/EmojiUtils';
    21  import * as FileUtils from '@libs/fileDownload/FileUtils';
    22  import isEnterWhileComposition from '@libs/KeyboardShortcut/isEnterWhileComposition';
    23  import CONST from '@src/CONST';
    24
    25  const excludeNoStyles: Array<keyof MarkdownStyle> = [];
    26  const excludeReportMentionStyle: Array<keyof MarkdownStyle> = ['mentionReport'];
    27  const imagePreviewAuthRequiredURLs = [CONST.EXPENSIFY_URL, CONST.STAGING_EXPENSIFY_URL];
    28
    29  // Enable Markdown parsing.
    30  // On web we like to have the Text Input field always focused so the user can easily type a new chat
    31  function Composer(
    32      {
    33          value,
    34          defaultValue,
    35          maxLines = -1,
    36          onKeyPress = () => {},
    37          style,
    38          autoFocus = false,
    39          shouldCalculateCaretPosition = false,
    40          isDisabled = false,
    41          onClear = () => {},
    42          onPasteFile = () => {},
    43          onSelectionChange = () => {},
    44          setIsFullComposerAvailable = () => {},
    45          checkComposerVisibility = () => false,
    46          selection: selectionProp = {
    47              start: 0,
    48              end: 0,
    49          },
    50          isComposerFullSize = false,
    51          shouldContainScroll = true,
    52          isGroupPolicyReport = false,
    53          ...props
    54      }: ComposerProps,
    55      ref: ForwardedRef<TextInput | HTMLInputElement>,
    56  ) {
    57      const textContainsOnlyEmojis = useMemo(() => EmojiUtils.containsOnlyEmojis(value ?? ''), [value]);
    58      const theme = useTheme();
    59      const styles = useThemeStyles();
    60      const markdownStyle = useMarkdownStyle(value, !isGroupPolicyReport ? excludeReportMentionStyle : excludeNoStyles);
    61      const StyleUtils = useStyleUtils();
    62      const textInput = useRef<AnimatedMarkdownTextInputRef | null>(null);
    63      const [selection, setSelection] = useState<
    64          | {
    65                start: number;
    66                end?: number;
    67                positionX?: number;
    68                positionY?: number;
    69            }
    70          | undefined
    71      >({
    72          start: selectionProp.start,
    73          end: selectionProp.end,
    74      });
    75      const [isRendered, setIsRendered] = useState(false);
    76      const isScrollBarVisible = useIsScrollBarVisible(textInput, value ?? '');
    77      const [prevScroll, setPrevScroll] = useState<number | undefined>();
    78      const isReportFlatListScrolling = useRef(false);
    79
    80      useEffect(() => {
    81          if (!!selection && selectionProp.start === selection.start && selectionProp.end === selection.end) {
    82              return;
    83          }
    84          setSelection(selectionProp);
    85          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    86      }, [selectionProp]);
    87
    88      /**
    89       *  Adds the cursor position to the selection change event.
    90       */
    91      const addCursorPositionToSelectionChange = (event: NativeSyntheticEvent<TextInputSelectionChangeEventData>) => {
    92          const webEvent = event as BaseSyntheticEvent<TextInputSelectionChangeEventData>;
    93          const sel = window.getSelection();
    94          if (shouldCalculateCaretPosition && isRendered && sel) {
    95              const range = sel.getRangeAt(0).cloneRange();
    96              range.collapse(true);
    97              const rect = range.getClientRects()[0] || range.startContainer.parentElement?.getClientRects()[0];
    98              const containerRect = textInput.current?.getBoundingClientRect();
    99
   100              let x = 0;
   101              let y = 0;
   102              if (rect && containerRect) {
   103                  x = rect.left - containerRect.left;
   104                  y = rect.top - containerRect.top + (textInput?.current?.scrollTop ?? 0) - rect.height / 2;
   105              }
   106
   107              const selectionValue = {
   108                  start: webEvent.nativeEvent.selection.start,
   109                  end: webEvent.nativeEvent.selection.end,
   110                  positionX: x - CONST.SPACE_CHARACTER_WIDTH,
   111                  positionY: y,
   112              };
   113
   114              onSelectionChange({
   115                  ...webEvent,
   116                  nativeEvent: {
   117                      ...webEvent.nativeEvent,
   118                      selection: selectionValue,
   119                  },
   120              });
   121              setSelection(selectionValue);
   122          } else {
   123              onSelectionChange(webEvent);
   124              setSelection(webEvent.nativeEvent.selection);
   125          }
   126      };
   127
   128      /**
   129       * Check the paste event for an attachment, parse the data and call onPasteFile from props with the selected file,
   130       * Otherwise, convert pasted HTML to Markdown and set it on the composer.
   131       */
   132      const handlePaste = useCallback(
   133          (event: ClipboardEvent) => {
   134              const isVisible = checkComposerVisibility();
   135              const isFocused = textInput.current?.isFocused();
   136              const isContenteditableDivFocused = document.activeElement?.nodeName === 'DIV' && document.activeElement?.hasAttribute('contenteditable');
   137
   138              if (!(isVisible || isFocused)) {
   139                  return true;
   140              }
   141
   142              if (textInput.current !== event.target && !(isContenteditableDivFocused && !event.clipboardData?.files.length)) {
   143                  const eventTarget = event.target as HTMLInputElement | HTMLTextAreaElement | null;
   144                  // To make sure the composer does not capture paste events from other inputs, we check where the event originated
   145                  // If it did originate in another input, we return early to prevent the composer from handling the paste
   146                  const isTargetInput = eventTarget?.nodeName === 'INPUT' || eventTarget?.nodeName === 'TEXTAREA' || eventTarget?.contentEditable === 'true';
   147                  if (isTargetInput || (!isFocused && isContenteditableDivFocused && event.clipboardData?.files.length)) {
   148                      return true;
   149                  }
   150
   151                  textInput.current?.focus();
   152              }
   153
   154              event.preventDefault();
   155
   156              const TEXT_HTML = 'text/html';
   157
   158              const clipboardDataHtml = event.clipboardData?.getData(TEXT_HTML) ?? '';
   159
   160              // If paste contains files, then trigger file management
   161              if (event.clipboardData?.files.length && event.clipboardData.files.length > 0) {
   162                  // Prevent the default so we do not post the file name into the text box
   163                  onPasteFile(event.clipboardData.files[0]);
   164                  return true;
   165              }
   166
   167              // If paste contains base64 image
   168              if (clipboardDataHtml?.includes(CONST.IMAGE_BASE64_MATCH)) {
   169                  const domparser = new DOMParser();
   170                  const pastedHTML = clipboardDataHtml;
   171                  const embeddedImages = domparser.parseFromString(pastedHTML, TEXT_HTML)?.images;
   172
   173                  if (embeddedImages.length > 0 && embeddedImages[0].src) {
   174                      const src = embeddedImages[0].src;
   175                      const file = FileUtils.base64ToFile(src, 'image.png');
   176                      onPasteFile(file);
   177                      return true;
   178                  }
   179              }
   180
   181              // If paste contains image from Google Workspaces ex: Sheets, Docs, Slide, etc
   182              if (clipboardDataHtml?.includes(CONST.GOOGLE_DOC_IMAGE_LINK_MATCH)) {
   183                  const domparser = new DOMParser();
   184                  const pastedHTML = clipboardDataHtml;
   185                  const embeddedImages = domparser.parseFromString(pastedHTML, TEXT_HTML).images;
   186
   187                  if (embeddedImages.length > 0 && embeddedImages[0]?.src) {
   188                      const src = embeddedImages[0].src;
   189                      if (src.includes(CONST.GOOGLE_DOC_IMAGE_LINK_MATCH)) {
   190                          fetch(src)
   191                              .then((response) => response.blob())
   192                              .then((blob) => {
   193                                  const file = new File([blob], 'image.jpg', {type: 'image/jpeg'});
   194                                  onPasteFile(file);
   195                              });
   196                          return true;
   197                      }
   198                  }
   199              }
   200              return false;
   201          },
   202          [onPasteFile, checkComposerVisibility],
   203      );
   204
   205      useEffect(() => {
   206          if (!textInput.current) {
   207              return;
   208          }
   209          const debouncedSetPrevScroll = lodashDebounce(() => {
   210              if (!textInput.current) {
   211                  return;
   212              }
   213              setPrevScroll(textInput.current.scrollTop);
   214          }, 100);
   215
   216          textInput.current.addEventListener('scroll', debouncedSetPrevScroll);
   217          return () => {
   218              textInput.current?.removeEventListener('scroll', debouncedSetPrevScroll);
   219          };
   220      }, []);
   221
   222      useEffect(() => {
   223          const scrollingListener = DeviceEventEmitter.addListener(CONST.EVENTS.SCROLLING, (scrolling: boolean) => {
   224              isReportFlatListScrolling.current = scrolling;
   225          });
   226
   227          return () => scrollingListener.remove();
   228      }, []);
   229
   230      useEffect(() => {
   231          const handleWheel = (e: MouseEvent) => {
   232              if (isReportFlatListScrolling.current) {
   233                  e.preventDefault();
   234                  return;
   235              }
   236              e.stopPropagation();
   237          };
   238          textInput.current?.addEventListener('wheel', handleWheel, {passive: false});
   239
   240          return () => {
   241              textInput.current?.removeEventListener('wheel', handleWheel);
   242          };
   243      }, []);
   244
   245      useEffect(() => {
   246          if (!textInput.current || prevScroll === undefined) {
   247              return;
   248          }
   249          // eslint-disable-next-line react-compiler/react-compiler
   250          textInput.current.scrollTop = prevScroll;
   251          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   252      }, [isComposerFullSize]);
   253
   254      useHtmlPaste(textInput, handlePaste, true);
   255
   256      useEffect(() => {
   257          setIsRendered(true);
   258      }, []);
   259
   260      const clear = useCallback(() => {
   261          if (!textInput.current) {
   262              return;
   263          }
   264
   265          const currentText = textInput.current.value;
   266          textInput.current.clear();
   267
   268          // We need to reset the selection to 0,0 manually after clearing the text input on web
   269          const selectionEvent = {
   270              nativeEvent: {
   271                  selection: {
   272                      start: 0,
   273                      end: 0,
   274                  },
   275              },
   276          } as NativeSyntheticEvent<TextInputSelectionChangeEventData>;
   277          onSelectionChange(selectionEvent);
   278          setSelection({start: 0, end: 0});
   279
   280          onClear(currentText);
   281      }, [onClear, onSelectionChange]);
   282
   283      useImperativeHandle(
   284          ref,
   285          () => {
   286              const textInputRef = textInput.current;
   287              if (!textInputRef) {
   288                  throw new Error('textInputRef is not available. This should never happen and indicates a developer error.');
   289              }
   290
   291              return {
   292                  ...textInputRef,
   293                  // Overwrite clear with our custom implementation, which mimics how the native TextInput's clear method works
   294                  clear,
   295                  // We have to redefine these methods as they are inherited by prototype chain and are not accessible directly
   296                  blur: () => textInputRef.blur(),
   297                  focus: () => textInputRef.focus(),
   298                  get scrollTop() {
   299                      return textInputRef.scrollTop;
   300                  },
   301              };
   302          },
   303          [clear],
   304      );
   305
   306      const handleKeyPress = useCallback(
   307          (e: NativeSyntheticEvent<TextInputKeyPressEventData>) => {
   308              // Prevent onKeyPress from being triggered if the Enter key is pressed while text is being composed
   309              if (!onKeyPress || isEnterWhileComposition(e as unknown as KeyboardEvent)) {
   310                  return;
   311              }
   312
   313              onKeyPress(e);
   314          },
   315          [onKeyPress],
   316      );
   317
   318      const scrollStyleMemo = useMemo(() => {
   319          if (shouldContainScroll) {
   320              return isScrollBarVisible ? [styles.overflowScroll, styles.overscrollBehaviorContain] : styles.overflowHidden;
   321          }
   322          return styles.overflowAuto;
   323      }, [shouldContainScroll, styles.overflowAuto, styles.overflowScroll, styles.overscrollBehaviorContain, styles.overflowHidden, isScrollBarVisible]);
   324
   325      const inputStyleMemo = useMemo(
   326          () => [
   327              StyleSheet.flatten([style, {outline: 'none'}]),
   328              StyleUtils.getComposeTextAreaPadding(isComposerFullSize),
   329              Browser.isMobileSafari() || Browser.isSafari() ? styles.rtlTextRenderForSafari : {},
   330              scrollStyleMemo,
   331              StyleUtils.getComposerMaxHeightStyle(maxLines, isComposerFullSize),
   332              isComposerFullSize ? {height: '100%', maxHeight: 'none'} : undefined,
   333              textContainsOnlyEmojis ? styles.onlyEmojisTextLineHeight : {},
   334          ],
   335
   336          [style, styles.rtlTextRenderForSafari, styles.onlyEmojisTextLineHeight, scrollStyleMemo, StyleUtils, maxLines, isComposerFullSize, textContainsOnlyEmojis],
   337      );
   338
   339      return (
   340          <RNMarkdownTextInput
   341              id={CONST.COMPOSER.NATIVE_ID}
   342              autoComplete="off"
   343              autoCorrect={!Browser.isMobileSafari()}
   344              placeholderTextColor={theme.placeholderText}
   345              ref={(el) => (textInput.current = el)}
   346              selection={selection}
   347              style={[inputStyleMemo]}
   348              markdownStyle={markdownStyle}
   349              value={value}
   350              defaultValue={defaultValue}
   351              autoFocus={autoFocus}
   352              /* eslint-disable-next-line react/jsx-props-no-spreading */
   353              {...props}
   354              onSelectionChange={addCursorPositionToSelectionChange}
   355              onContentSizeChange={(e) => {
   356                  updateIsFullComposerAvailable({maxLines, isComposerFullSize, isDisabled, setIsFullComposerAvailable}, e, styles);
   357              }}
   358              disabled={isDisabled}
   359              onKeyPress={handleKeyPress}
   360              addAuthTokenToImageURLCallback={addEncryptedAuthTokenToURL}
   361              imagePreviewAuthRequiredURLs={imagePreviewAuthRequiredURLs}
   362          />
   363      );
   364  }
   365
   366  Composer.displayName = 'Composer';
   367
   368  export default React.forwardRef(Composer);

